.roof-measured-lines li.is-incomplete .roof-measured-line-length small {
  color: var(--sf-danger-text);
}

.roof-measured-lines li.is-incomplete select {
  border-color: var(--sf-danger-border);
  color: var(--sf-danger-text);
}

